import{c as s,Z as d,Q as r,j as n,g as a,n as l,o as e,av as i,m as p}from"./chunks/framework.rWdQudnF.js";const f=JSON.parse('{"title":"存储管理","description":"","frontmatter":{"title":"存储管理"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/存储管理/存储管理.md","filePath":"综合知识/系统基础/操作系统/存储管理/存储管理.md","lastUpdated":null}'),u={name:"综合知识/系统基础/操作系统/存储管理/存储管理.md"};function c(g,t,h,b,m,q){const o=d("font");return r(),n("div",null,[t[3]||(t[3]=a("h2",{id:"考点清单",tabindex:"-1"},[l("考点清单 "),a("a",{class:"header-anchor",href:"#考点清单","aria-label":'Permalink to "考点清单"'},"​")],-1)),t[4]||(t[4]=a("ul",null,[a("li",null,"[x] 分区存储管理（固定/可变/可重定位，分配算法） ✅ 2026-05-15"),a("li",null,"[x] 分页存储管理 → 详见子文件 ✅ 2026-05-15"),a("li",null,"[x] 分段存储管理 ✅ 2026-05-15"),a("li",null,"[x] 段页式存储管理 ✅ 2026-05-15")],-1)),t[5]||(t[5]=a("h2",{id:"笔记",tabindex:"-1"},[l("笔记 "),a("a",{class:"header-anchor",href:"#笔记","aria-label":'Permalink to "笔记"'},"​")],-1)),a("p",null,[t[1]||(t[1]=l("四种存储管理方式的本质区别在于",-1)),e(o,{color:"#f79646"},{default:i(()=>[...t[0]||(t[0]=[l("如何将进程的逻辑地址映射到物理内存",-1)])]),_:1}),t[2]||(t[2]=l("：",-1))]),t[6]||(t[6]=p(`<p>核心区别一览</p><table tabindex="0"><thead><tr><th>对比维度</th><th>分区存储</th><th>分页存储</th><th>分段存储</th><th>段页式存储</th></tr></thead><tbody><tr><td><strong>分配单位</strong></td><td>整个进程（整存）</td><td>固定大小页框</td><td>可变大小段</td><td>先分可变段，再分固定页</td></tr><tr><td><strong>地址结构</strong></td><td>基址+偏移</td><td>页号+页内偏移</td><td>段号+段内偏移</td><td>段号+页号+页内偏移</td></tr><tr><td><strong>碎片类型</strong></td><td>内部/外部碎片</td><td>内部碎片（极小）</td><td>外部碎片</td><td>极小碎片</td></tr><tr><td><strong>用户可见性</strong></td><td>不可见</td><td>透明（用户无感）</td><td>可见（按逻辑分段）</td><td>部分可见</td></tr><tr><td><strong>共享/保护</strong></td><td>困难</td><td>较困难</td><td><strong>容易</strong>（按段共享）</td><td>容易</td></tr><tr><td><strong>动态链接</strong></td><td>不支持</td><td>不支持</td><td>支持</td><td>支持</td></tr></tbody></table><hr><h3 id="分区存储管理" tabindex="-1">分区存储管理 <a class="header-anchor" href="#分区存储管理" aria-label="Permalink to &quot;分区存储管理&quot;">​</a></h3><blockquote><p>🎯 一句话结论：分区管理是&quot;整存&quot; — 固定分区产生内部碎片，可变分区产生外部碎片。</p></blockquote><p><strong>整存</strong>，将进程所需内存整体一起分配。</p><table tabindex="0"><thead><tr><th>方式</th><th>特点</th></tr></thead><tbody><tr><td>固定分区</td><td>静态分区，产生内部碎片</td></tr><tr><td>可变分区</td><td>动态分区，产生外部碎片</td></tr><tr><td>可重定位分区</td><td>移动已分配区域合并碎片，仅在外部请求无法满足时触发</td></tr></tbody></table><p><strong>可变分区分配算法</strong>：</p><table tabindex="0"><thead><tr><th>算法</th><th>策略</th></tr></thead><tbody><tr><td>首次适应法</td><td>从头查找，找到第一个 &gt;= 所需空间的空间块</td></tr><tr><td>最佳适应法</td><td>空闲块按大小排序，找最接近的</td></tr><tr><td>最差适应法</td><td>找最大的空闲块，防止产生过多细小碎片</td></tr><tr><td>循环首次适应法</td><td>从上次分配位置继续查找，不每次从头开始</td></tr></tbody></table><p><strong>可变分区分配算法</strong>：首次适应（从头找第1个够的）→ 最佳适应（找最接近的）→ 最差适应（找最大的）→ 循环首次适应（从上一次位置继续）</p><h3 id="分段存储管理" tabindex="-1">分段存储管理 <a class="header-anchor" href="#分段存储管理" aria-label="Permalink to &quot;分段存储管理&quot;">​</a></h3><blockquote><p>🎯 一句话结论：段表包含<strong>段长和基址</strong>。偏移 &gt; 段长即为<strong>地址越界</strong>。</p></blockquote><p>将进程空间按逻辑整体分段，段表包含<strong>段长和基址</strong>两个属性来确定逻辑段在物理段中的位置。</p><ul><li>优点：多道程序共享内存，各段修改互不影响</li><li>缺点：内存利用率低，内存碎片浪费大</li></ul><blockquote><p>地址越界判断：逻辑地址 (段号, 偏移) 中偏移 &gt; 段长 则为越界。常见错误原因是<strong>逻辑地址转换物理地址时地址越界</strong>，根源通常是数组下标越界没有检查。</p></blockquote><h3 id="分页存储管理" tabindex="-1">分页存储管理 <a class="header-anchor" href="#分页存储管理" aria-label="Permalink to &quot;分页存储管理&quot;">​</a></h3><p>详见：<a href="/arch-exam/综合知识/系统基础/操作系统/存储管理/分页存储管理.html">架构师-备考 综合知识-系统基础-操作系统-分页存储管理</a></p><p>逻辑页分为页号和页内地址，通过页表查询页号对应的物理块号。相关概念：页面置换算法（最优算法、先进先出、最近最少使用）、快表。</p><h3 id="段页式存储管理" tabindex="-1">段页式存储管理 <a class="header-anchor" href="#段页式存储管理" aria-label="Permalink to &quot;段页式存储管理&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>先分段，后分页</strong>。空间浪费小、共享容易、保护容易、能动态链接。</p></blockquote><ul><li>优点：空间浪费小、存储共享容易、存储保护容易、能动态链接</li><li>缺点：管理软件复杂度和开销增加，执行速度下降</li></ul><h3 id="拓展理解" tabindex="-1">拓展理解 <a class="header-anchor" href="#拓展理解" aria-label="Permalink to &quot;拓展理解&quot;">​</a></h3><h4 id="场景化理解四种存储方式" tabindex="-1">场景化理解四种存储方式 <a class="header-anchor" href="#场景化理解四种存储方式" aria-label="Permalink to &quot;场景化理解四种存储方式&quot;">​</a></h4><p>四种方式的本质区别在于<strong>如何把程序用的逻辑地址翻译成物理内存的真实地址</strong>。程序员写 <code>arr[10]</code>、<code>func()</code> 时用的是逻辑地址，CPU执行指令时，MMU（硬件）自动查表翻译，程序员完全无感。</p><p>下面用生活场景帮你建立直观感受。</p><p><strong>① 分区存储 — &quot;租公寓&quot;</strong></p><p>好比你要住，给你一整间连续的公寓。你说&quot;房间1040号&quot;，管理员知道公寓从2000号开始，直接算出3040号。简单粗暴。</p><p>但问题是：租客来了又走，内存变得支离破碎——一块100KB的空地可能被拆成好几个小洞，新来的大租客装不下。固定分区产生<strong>内部碎片</strong>（租了大房间只住一半），可变分区产生<strong>外部碎片</strong>（小洞凑不出大空间）。</p><p><strong>② 分页存储 — &quot;图书馆散页&quot; 🔥 最常用</strong></p><p>把程序（一本书）拆成4KB一页的散页，物理内存（图书馆）切成同样大小的书架格子。每页可以放在任意空位，<strong>不需要连续</strong>。</p><p>你想看书的第1040页内容？先查页号（0号页），翻索引卡（页表）找到它在5号书架的格子里，去那里取。页表就是一张&quot;逻辑页号→物理格子号&quot;的映射表。</p><p>✅ 核心优势：不连续也没关系，外部碎片几乎消失。还支持<strong>虚拟内存</strong>——书太厚，只把当前要读的几页放桌上（内存），其余放柜子里（硬盘），读到不在桌上的页时触发&quot;缺页中断&quot;去柜子取。</p><p>③ <strong>分段存储 — &quot;图书馆功能区&quot;</strong></p><p>图书馆按功能分区：小说区（基址A，占5000本）、参考书区（基址B，占200本）。你说&quot;参考书区的第1040本&quot;，管理员先去参考书区基址，再加1040，还得检查有没有超出该区容量——越界了就不合法。</p><p>每个段在段表里记着两个值：<strong>基址（从哪开始）+ 段长（多大）</strong>。偏移 &gt; 段长 → 地址越界，常见根源是数组下标越界没检查。</p><p>✅ 优势：按逻辑单位分段，共享容易（两个进程指向同一个代码段即可），支持动态链接。</p><p>④ <strong>段页式存储 — &quot;先分功能区，每个功能区内部再拆散页&quot;</strong></p><p>图书馆先分区（小说区、参考书区），每个区内再拆散页放。地址 = 段号 + 页号 + 页内偏移。</p><p>集两家之长：既有分段共享和保护的能力，又有分页消除碎片的能力。</p><hr><p><strong>历史演进（为什么今天大家都在用分页）：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1960s  分区存储  → 整存整取，碎片严重</span></span>
<span class="line"><span>1970s  分段存储  → 按逻辑段分，外部碎片仍在</span></span>
<span class="line"><span>1980s  分页存储  → 固定4KB ✅ 碎片极小+虚拟内存 → 成为主流</span></span>
<span class="line"><span>1990s至今      → Linux/Windows 纯分页</span></span></code></pre></div><p><strong>操作系统怎么选？</strong> 不是运行时选的，是OS写内核时就定死了。Linux/Windows 都用分页，因为只有分页支持虚拟内存。x86 硬件其实同时提供了分段和分页两套翻译单元，但 Linux/Windows 把分段&quot;催眠&quot;了（所有段基址设0、段长设满），实际只靠分页。</p><p><strong>一句话速记：</strong></p><table tabindex="0"><thead><tr><th>策略</th><th>一句话</th></tr></thead><tbody><tr><td>分区</td><td>包场一个连续房间，基址+偏移</td></tr><tr><td>分页</td><td>书拆散页任意放，查索引卡找</td></tr><tr><td>分段</td><td>按功能区划分，每区有基址+大小限制</td></tr><tr><td>段页式</td><td>先分功能区，每个功能区内部再拆散页</td></tr></tbody></table><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p><strong>[Q2] 段式存储-越界判断</strong></p><p>假设系统采用段式存储管理方法，进程P的段表如下所示。逻辑地址（ ）不能转换为对应的物理地址。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260515220735.png" alt="image.png"></p><ul><li>A. (0，790)和(2，88)</li><li>B. (1，30)和(3，290)</li><li>C. (2，88)和(4，98)</li><li>D. (0，810)和(4，120)</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：段0段长800，偏移810&gt;800越界；段4段长100，偏移120&gt;100越界。</p></div></details><hr><p><strong>[Q3] 段式存储-越界原因</strong></p><p>假设系统采用段式存储管理方法。逻辑地址不能转换为对应的物理地址；不能转换的原因是进行（ ）。</p><ul><li>A. 除法运算时除数为零</li><li>B. 算术运算时有溢出</li><li>C. 逻辑地址到物理地址转换时地址越界</li><li>D. 物理地址到逻辑地址转换时地址越界</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：偏移&gt;段长→地址越界，发生在逻辑地址→物理地址转换过程中。</p></div></details><hr><p><strong>[Q31] 段式存储-越界根源</strong></p><p>假设系统采用段式存储管理方法，逻辑地址不能转换为对应的物理地址，可能的原因是（ ）。</p><ul><li>A. 数组下标运算没有检查是否越界</li><li>B. 除零错</li><li>C. 内存段分配失败</li><li>D. 页面不在内存中</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：段越界的常见根源是程序数组下标越界未检查，导致段内偏移超出段长。</p></div></details><hr><p><strong>[Q51] 段页式地址</strong></p><p>在段页式存储管理中，逻辑地址由（ ）组成。</p><ul><li>A. 段号、页号和页内偏移量</li><li>B. 段号和段内偏移量</li><li>C. 页号和页内偏移量</li><li>D. 段号和页号</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：段页式=先分段再分页，逻辑地址=段号+页号+页内偏移。</p></div></details>`,66))])}const y=s(u,[["render",c]]);export{f as __pageData,y as default};
